import org.junit.Test;
import org.junit.Assert;

public class UnknownClassTest {

    @Test
    public void testCase1() {
        Assert.assertEquals(0.0, calculateBonus(0.0, "regular"), 0.00001);
    }

    @Test
    public void testCase2() {
        Assert.assertEquals(7.5, calculateBonus(150.0, "regular"), 0.00001);
    }

    @Test
    public void testCase3() {
        Assert.assertEquals(0.0, calculateBonus(50.0, "regular"), 0.00001);
    }

    @Test
    public void testCase4() {
        Assert.assertEquals(15.0, calculateBonus(150.0, "premium"), 0.00001);
    }

    @Test
    public void testCase5() {
        Assert.assertEquals(1.0, calculateBonus(50.0, "premium"), 0.00001);
    }

    @Test
    public void testCase6() {
        Assert.assertEquals(0.0, calculateBonus(100.0, "unknown"), 0.00001);
    }

    @Test
    public void testCase7() {
        Assert.assertEquals(0.0, calculateBonus(100.0, ""), 0.00001);
    }

    @Test
    public void testCase8() {
        Assert.assertEquals(0.0, calculateBonus(100.0, null), 0.00001);
    }

    private double calculateBonus(double sales, String level) {
        if (level == null || level.isEmpty()) {
            return 0.0;
        }
        switch (level) {
            case "regular":
                if (sales > 100) {
                    return (sales - 100) * 0.15;
                } else {
                    return 0.0;
                }
            case "premium":
                return sales * 0.1;
            default:
                return 0.0;
        }
    }
}

