import org.junit.Test;
import static org.junit.Assert.*;

public class HypotheticalTest {

    private String hypotheticalMethod(int num, boolean flag) {
        if (num > 10 && flag) return "Large Positive";
        if (num > 0 && flag) return "Small Positive";
        if (num < -5 && !flag) return "Large Negative";
        if (num < 0 && !flag) return "Small Negative";
        return "Other";
    }

    @Test
    public void testCase1() {
        assertEquals("Large Positive", hypotheticalMethod(12, true));
    }

    @Test
    public void testCase2() {
        assertEquals("Small Positive", hypotheticalMethod(5, true));
    }

    @Test
    public void testCase3() {
        assertEquals("Large Negative", hypotheticalMethod(-6, false));
    }

    @Test
    public void testCase4() {
        assertEquals("Small Negative", hypotheticalMethod(-2, false));
    }
}

