import org.junit.Test;
import org.junit.Assert;

public class DecodeHexDigitTest {

    @Test
    public void testCase1() {
        Assert.assertEquals(-1, decodeHexDigit('춠'));
    }

    @Test
    public void testCase2() {
        Assert.assertEquals(-1, decodeHexDigit('J'));
    }

    @Test
    public void testCase3() {
        Assert.assertEquals(-1, decodeHexDigit('\x00'));
    }

    @Test
    public void testCase4() {
        Assert.assertEquals(8, decodeHexDigit('8'));
    }

    @Test
    public void testCase5() {
        Assert.assertEquals(15, decodeHexDigit('F'));
    }

    @Test
    public void testCase6() {
        Assert.assertEquals(14, decodeHexDigit('e'));
    }

    private int decodeHexDigit(char hexChar) {
        if (hexChar >= '0' && hexChar <= '9') {
            return hexChar - '0';
        } else if (hexChar >= 'A' && hexChar <= 'F') {
            return hexChar - 'A' + 10;
        } else if (hexChar >= 'a' && hexChar <= 'f') {
            return hexChar - 'a' + 10;
        } else {
            return -1;
        }
    }
}

